/**
 * Module implementing overslime and overslime helpers.
 * TODO 1.21: register as a singleton loader and migrate OverslimeModifier to JSON.
 */
public class OverslimeModule extends CapacityBarHook.PersistentDataCapacityBar {
  private static final List<ModuleHook<?>> DEFAULT_HOOKS = HookProvider.<OverslimeModule>defaultHooks(ModifierHooks.CAPACITY_BAR);
  /** Singleton instance */
  public static final OverslimeModule INSTANCE = new OverslimeModule();

  /** Stat for the overslime cap, copies the durability global multiplier on build */
  public static final FloatToolStat OVERSLIME_STAT = new IntegerToolStat(new ToolStatId(TConstruct.MOD_ID, "overslime"), 0xFF71DC85, 0, 0, Short.MAX_VALUE, TinkerTags.Items.DURABILITY) {
    @Override
    public Float build(ModifierStatsBuilder parent, Object builderObj) {
      return super.build(parent, builderObj) * parent.getMultiplier(ToolStats.DURABILITY);
    }
  };

  private OverslimeModule() {
    super(TinkerModifiers.overslime.getId());
  }

  @Override
  public List<ModuleHook<?>> getDefaultHooks() {
    return DEFAULT_HOOKS;
  }

  /**
   * Sets the shield, bypassing the capacity.
   * @param persistentData  Persistent data
   * @param amount          Amount to set
   */
  public void setAmountRaw(ModDataNBT persistentData, int amount) {
    if (amount <= 0) {
      persistentData.remove(key);
    } else {
      persistentData.putInt(key, amount);
    }
  }

  /** Gets the overslime capacity on the tool */
  public static int getCapacity(IToolStackView tool) {
    return tool.getStats().getInt(OVERSLIME_STAT);
  }

  @Override
  public int getCapacity(IToolStackView tool, ModifierEntry entry) {
    return getCapacity(tool);
  }

  /** Gets the boost to apply from overworked */
  public static int getOverworkedBonus(IToolStackView tool) {
    return (1 + tool.getModifierLevel(TinkerModifiers.overworked.getId()));
  }

  @Override
  public void addAmount(IToolStackView tool, ModifierEntry entry, int amount) {
    // yeah, I am hardcoding overworked. If you need something similar, put in an issue request on github
    // grants +100% restoring per level
    super.addAmount(tool, entry, amount * getOverworkedBonus(tool));
  }

  /** Helper to add amount without worrying about the modifier entry */
  public void addAmount(IToolStackView tool, int amount) {
    addAmount(tool, ModifierEntry.EMPTY, amount);
  }

  /** Removes overslime from a tool. Unlike {@link #addAmount(IToolStackView, int)}, does not trigger overworked */
  public void removeAmount(IToolStackView tool, int amount) {
    removeAmount(tool, ModifierEntry.EMPTY, amount);
  }
}

package slimeknights.tconstruct.library.tools.capability.fluid;

import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.resources.ResourceLocation;
import net.minecraftforge.fluids.FluidStack;
import slimeknights.mantle.Mantle;
import slimeknights.mantle.data.registry.NamedComponentRegistry;
import slimeknights.tconstruct.TConstruct;
import slimeknights.tconstruct.library.modifiers.modules.ModifierModule;
import slimeknights.tconstruct.library.modifiers.modules.build.ModifierTraitModule;
import slimeknights.tconstruct.library.tools.nbt.IToolStackView;
import slimeknights.tconstruct.library.tools.stat.CapacityStat;
import slimeknights.tconstruct.library.tools.stat.INumericToolStat;
import slimeknights.tconstruct.library.tools.stat.ToolStatId;
import slimeknights.tconstruct.tools.TinkerModifiers;

import java.util.function.BiFunction;

/** Helper methods for handling fluids in tools */
@SuppressWarnings("ClassCanBeRecord")  // want to leave extendable
@Getter
@RequiredArgsConstructor
public class ToolTankHelper {
  /** Helper function to parse a fluid from NBT */
  public static final BiFunction<CompoundTag, String, FluidStack> PARSE_FLUID = (nbt, key) -> FluidStack.loadFluidStackFromNBT(nbt.getCompound(key));

  /** Format key for the stat */
  public static final String MB_FORMAT = Mantle.makeDescriptionId("gui", "fluid.millibucket");
  /** Stat controlling the max for the default helper */
  public static final CapacityStat CAPACITY_STAT = new CapacityStat(new ToolStatId(TConstruct.MOD_ID, "tank_capacity"), 0xA0A0A0, MB_FORMAT);
  /** Default tank helper for setting fluids */
  public static final ToolTankHelper TANK_HELPER = new ToolTankHelper(CAPACITY_STAT, TConstruct.getResource("tank_fluid"));
  /** Module ensuring the tool has the tank */
  public static final ModifierModule TANK_HANDLER = new ModifierTraitModule(TinkerModifiers.tankHandler.getId(), 1, true);

  /** Loadable instance for JSON */
  public static final NamedComponentRegistry<ToolTankHelper> LOADABLE = new NamedComponentRegistry<>("Unknown Tool Tank Helper");

  /** Tool stat handling max tank capacity */
  private final INumericToolStat<?> capacityStat;
  /** Key in persistent data storing the fluid */
  private final ResourceLocation fluidKey;

  /** Gets the capacity for the tool */
  public int getCapacity(IToolStackView tool) {
    return tool.getStats().getInt(capacityStat);
  }


  /* Fluid */

  /** Gets the fluid in the tank */
  public FluidStack getFluid(IToolStackView tool) {
    return tool.getPersistentData().get(getFluidKey(), PARSE_FLUID);
  }

  /** Sets the fluid in the tank */
  public FluidStack setFluid(IToolStackView tool, FluidStack fluid) {
    if (fluid.isEmpty()) {
      tool.getPersistentData().remove(fluidKey);
      return FluidStack.EMPTY;
    }
    int capacity = getCapacity(tool);
    // we always copy before saving to ensure the NBT on the fluid gets copied, since those being the same compound is possible
    fluid = fluid.copy();
    if (fluid.getAmount() > capacity) {
      fluid.setAmount(capacity);
    }
    tool.getPersistentData().put(fluidKey, fluid.writeToNBT(new CompoundTag()));
    return fluid;
  }
}

